// Generated by hecks site site_projection.project_site. Do not edit.

// The editor's own sign-in page, for the site whose Editor row names a `sign_in` address. A person
// with no session is sent here instead of to the site's admin login, which lets in only the roles
// that administer the site; this page is for everyone the membership list admits to edit. It starts
// the host's own sign-in (Google), which sets the session cookie on the site's origin, and the
// editor admits whoever that cookie names and the list holds (see `enterFromSite` in app.ts). It
// says what the host's redirect may show them on the way, and that they come back here.
import { assetUrl, isBuilt } from "../assets.ts";
import { EDITOR } from "../config.ts";
import { esc, href } from "./html.ts";

/** What the sign-in page may say went wrong. */
export type LoginNote = "signed-out" | "refused" | "again";

const NOTES: Record<LoginNote, string> = {
  "signed-out": "You are signed out.",
  refused: "That account is not on the list of people who may edit here. Ask an administrator to add you, then sign in again.",
  again: "Your sign-in ran out. Sign in again to carry on.",
};

/** The page, as a whole document: no navigation, since there is nothing here to go to. */
export function loginPage(note: LoginNote | null = null): string {
  const sheet = isBuilt() ? `<link rel="stylesheet" href="${esc(assetUrl("editor.css"))}">` : "";
  const said = note ? `<p class="alert alert-info alert-soft mt-4" role="status">${esc(NOTES[note])}</p>` : "";
  const start = EDITOR.signIn ?? href("login");
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light dark">
<title>Sign in - ${esc(EDITOR.title)}</title>
<script src="${esc(assetUrl("theme.js"))}"></script>
${sheet}
</head>
<body class="min-h-screen bg-base-200 text-base-content">
<main id="main" class="mx-auto grid min-h-screen w-full max-w-md content-center gap-4 px-4 py-10">
<div class="border border-base-300 bg-base-100 p-6">
<p class="text-sm font-semibold text-muted">${esc(EDITOR.brand || EDITOR.title)}</p>
<h1 class="mt-1 text-2xl">Sign in to edit the site</h1>
<p class="mt-3 text-muted">Use the Google account the administrator added for you.</p>
${said}
<p class="mt-6"><a class="btn btn-neutral w-full" href="${esc(start)}">Sign in with Google</a></p>
<p class="mt-6 text-sm text-muted">Signed in already, and the website's own page said you are not an administrator? That page is only the website's. <a class="link" href="${esc(href())}">Open the editor</a>.</p>
</div>
</main>
</body>
</html>
`;
}
